const rows = $input.all().map(i => i.json);
const day = 864e5, now = new Date();
const num = v => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const parse = v => { const d = new Date(v); return isNaN(d) ? null : d; };
const start = new Date(now - 7 * day), prevStart = new Date(now - 14 * day);
const dated = rows.map(r => ({ ...r, _d: parse(r.Date) }));
let week = dated.filter(r => r._d && r._d >= start && r._d < now);
const prev = dated.filter(r => r._d && r._d >= prevStart && r._d < start);
if (!week.length) week = dated; // dates not readable: use every row in the sheet
const revenue = week.reduce((s, r) => s + num(r.Amount), 0);
const items = week.reduce((s, r) => s + num(r.Qty), 0);
const prevRevenue = prev.reduce((s, r) => s + num(r.Amount), 0);
const byProduct = {}, byDay = {};
for (const r of week) {
  const p = r.Product || 'Other';
  byProduct[p] = byProduct[p] || { product: p, qty: 0, amount: 0 };
  byProduct[p].qty += num(r.Qty); byProduct[p].amount += num(r.Amount);
  const d = String(r.Date); byDay[d] = (byDay[d] || 0) + num(r.Amount);
}
const top = Object.values(byProduct).sort((a, b) => b.amount - a.amount);
const best = Object.entries(byDay).sort((a, b) => b[1] - a[1])[0] || ['-', 0];
return [{ json: {
  revenue: +revenue.toFixed(2), orders: week.length, items,
  average_order: week.length ? +(revenue / week.length).toFixed(2) : 0,
  previous_week_revenue: prevRevenue ? +prevRevenue.toFixed(2) : null,
  change_percent: prevRevenue ? Math.round((revenue - prevRevenue) / prevRevenue * 100) : null,
  top_products: top.slice(0, 5), best_day: { date: best[0], amount: +(+best[1]).toFixed(2) }
} }];

